# v12: found via a scripted-opponent test (NOTES.md "v12") that
# SHED_OVERFLOW_GUARD_THRESHOLD alone was far too late a backstop.
# HOLD_FLOOR_PCT's "wait for a recovery" logic implicitly assumes a
# TRANSIENT glut — it breaks down completely when TWO players both
# concentrate on the same crop, since the price then has no reason to ever
# recover while both keep producing it. Observed directly: MELON piled up
# to 64 units in the shed (price crashed to $1, hold floor still ~$103)
# while cash crashed to double digits, only forced to sell once the shed
# neared its hard 100-item cap — by which point most of that inventory's
# value was already lost to holding it at $1 instead of realizing SOME
# cash steadily. This scales the effective hold floor down as held
# quantity grows, reaching 0 (full capitulation, sell at any price) well
# before the shed is anywhere near full — a large accumulated pile is
# itself evidence the hoped-for recovery isn't coming, regardless of the
# exact price trajectory.
SELL_CAPITULATION_QTY = 30

# v13: SDD §6 flagged this from the start as a known limitation of the
# greedy-per-turn scheduler — only ONE crop's shortfall "wins" the
# planting slot each turn (by ratio, since M2's raw-count version starved
# whichever crop had the smaller target). A scripted single-crop opponent
# benchmark (NOTES.md "v12") made the cost of that concrete: our portfolio
# needs several turns in a row all landing on the SAME crop before another
# one gets a turn at all, while a script with only one crop to plant never
# pays that tax. Setting this True generates a PLANT candidate for every
# eligible crop (with seed stock and remaining shortfall) at every empty
# tile, instead of only the single best-by-ratio crop — the seed-overcommit
# cap in UnitScheduler.assign() is already keyed per-crop, so multiple
# crops landing in the same turn (via different idle units) is safe.
ENABLE_MULTI_CROP_PLANTING = True

# M6: keep a small opportunistic fertilizer reserve on hand (bought via
# BUY_PRODUCT, or from animal COLLECT_FERTILIZER) so FERTILIZE has something
# to consume — a whole yield-boost mechanic (README §Harvest Yields: doubles
# the per-day watering bonus for 3 days) that earlier milestones never used.
FERTILIZER_RESERVE_TARGET = 3

# v15: found via a "pass"-baseline seed sweep (NOTES.md "v15", the classic
# death-spiral test from v7/v8) — 7/10 seeds crashed to a permanent
# cash-crunch/weed spiral that v8 was supposed to have already fixed.
# Root cause: BOTH top-up builders below re-check "are we short of the
# reserve?" every single turn (unavoidable — feed/fertilizer gets consumed
# mid-day), but neither ever capped how much they'd PAY. FERTILIZER's
# small T=200 (README Price Function table) means repeated small buys
# across just a handful of turns ratchet its price up fast — one seed
# traced a SINGLE unit costing $202 (2x base) by the third re-buy that
# day, right in the pre-first-harvest cash-tight window (day 5-8) where
# every dollar spent here was a dollar not available to HIRE. Neither
# top-up is worth paying a steep premium for — missing a day's fertilize
# bonus or a feed top-up (there's still the untouched WHEAT tile
# allocation as backup) costs far less than the cash spent chasing an
# inflated price.
FERTILIZER_BUY_CEILING_MULT = 1.5   # never pay more than this x base_price for a top-up buy

# v20: WHEAT feed top-up used to share FERTILIZER_BUY_CEILING_MULT (1.5x)
# with fertilizer — found via a real-scripted-opponent trace to be a real
# bug, not a safe reuse: a day-by-day trace showed shed WHEAT sitting at
# 0 for a FULL day (hour 2 through 23) with healthy cash ($15k+) the
# whole time, and zero BUY_PRODUCT WHEAT orders issued despite
# `_build_wheat_feed_topup_orders` wanting to top up — because wheat's
# price had drifted to $39 (1.56x base $25), just over the shared 1.5x
# ceiling. The stakes are wildly asymmetric: missing a FERTILIZER top-up
# forfeits a minor yield bonus (the reasoning that justified 1.5x
# originally), but missing a WHEAT top-up risks losing an entire animal
# ($300-500 already spent) to a starvation escape — a much higher price
# premium is worth paying to prevent that. A 20-turn/220-critical-unfed-
# turn sample found shed WHEAT was 0 in 93% of turns with a
# critical-unfed animal present, and this ceiling collision is the
# confirmed mechanism.
WHEAT_FEED_BUY_CEILING_MULT = 4.0   # separate, much more generous ceiling — losing an animal costs far more than a pricey wheat top-up
# v28 (Rocket Turtle): re-tuned alongside TASK_SCORE_WEIGHTS/HOLD_FLOOR_PCT
# above — see the comment there for the Monte Carlo run and validation.
# Compresses early/buildout noticeably vs the old (4, 20, 27) boundaries.
PHASE_DAY_BOUNDARIES = {"early_end": 6, "buildout_end": 9, "scale_end": 19}

# SDD §5.1 endgame liquidation: with this few days left, dump everything in
# the shed regardless of hold floor — unsold inventory doesn't count toward
# the win condition (README "Reward"), so even a price-floor $1 sale beats
# holding stock that never gets sold.
LIQUIDATION_DAYS_REMAINING = 2

# --- v10: adaptive/opponent-aware extensions -----------------------------
# Discussed explicitly as an alternative to literal chess/Othello-style
# minimax, which doesn't fit this game (simultaneous moves not alternating
# turns, astronomical per-turn joint action space, reward resolves 240+
# turns after the decision that caused it, and the opponent's private
# state — cash, seed stock — is invisible so their legal-action set can't
# be enumerated for a real game tree). These three pieces instead extend
# the existing reactive opponent-awareness (OPPONENT_FLOOD_PENALTY) into
# something trend-predictive, and add a bounded local-cluster heuristic in
# place of true multi-turn search. All three are flag-gated so
# tools/tournament.py can A/B them against the pre-v10 baseline directly.

ENABLE_OPPONENT_TREND_TRACKING = True
# How many days back to compare against when estimating an opponent
# resource's growth rate (tiles/day). Shorter windows react faster to
# opponent behavior changes but are noisier turn to turn.
OPPONENT_TREND_WINDOW_DAYS = 5
# Multiplies the flood-penalty divisor per unit of measured daily growth
# rate on top of the existing per-tile OPPONENT_FLOOD_PENALTY — an
# opponent rapidly SCALING UP a crop is treated as a bigger threat than
# one holding a large but static tile count, since our own harvest lands
# after their growth has had more time to compound.
OPPONENT_GROWTH_PENALTY = 0.35

ENABLE_SUPPLY_PRESSURE_ADJUSTMENT = True
# Projected opponent daily production (visible tile/structure count x
# YIELD_PER_TILE_PER_DAY, scaled by their measured growth trend) beyond
# which we treat a resource's price as headed for a glut regardless of
# our own behavior, and shrink our own HOLD_FLOOR_PCT for it accordingly
# — better to sell into the crash early than hold for a recovery that
# incoming opponent supply makes less likely.
OPPONENT_SUPPLY_PRESSURE_THRESHOLD = 8.0  # units/day
OPPONENT_SUPPLY_PRESSURE_HOLD_DISCOUNT = 0.5  # multiplies HOLD_FLOOR_PCT down when pressure exceeds the threshold

ENABLE_CLUSTER_LOOKAHEAD = True
# Bounded stand-in for real multi-turn search (SDD §6's "v1.5 shallow
# lookahead" suggestion): rather than simulate future turns, score a
# candidate tile higher if OTHER actionable tiles already sit near it —
# a unit sent there this turn is well-positioned to chain into the next
# task efficiently, instead of finishing an isolated tile and needing a
# long return trip. Approximates the benefit of a real lookahead without
# reimplementing the game engine's transition function to simulate one.
CLUSTER_LOOKAHEAD_RADIUS = 2
# NOTE: an initial value of 8.0 was far too strong once actually measured —
# on a fully-empty 5x5 quadrant, a corner tile (~5 same-radius neighbors)
# vs a center tile (~12) differ by ~56 points at that setting, equivalent
# to ~9 tiles of distance cost. That overpowered even a unit standing
# directly ON a plantable tile (0 distance cost) into walking away from it
# for a marginally better-clustered neighbor (caught by a unit test).
# Dialed down so the bonus nudges ties, not overrides immediate zero-cost
# actions.
CLUSTER_LOOKAHEAD_BONUS_PER_NEIGHBOR = 1.0

# --- v11: direct market-trend signal + opponent-expansion mirroring ------
# Two lightweight (O(1)/turn) reactive heuristics, chosen over v11's third
# candidate proposal (a shallow MCTS with day-scale rollouts) after review:
# that would need a from-scratch forward simulator of the whole game engine
# (yield formulas, weed-spawn RNG, market/town updates — none of which we
# reimplement today), doesn't map cleanly onto a SIMULTANEOUS-move game
# without an opponent-response model we don't have, and "thousands of
# rollouts per decision" is measured against a free-standing laptop, not
# the actual 1.6 vCPU Kaggle evaluation budget our own turns run in
# (0.12ms/turn today — a single 48-72 turn rollout alone would already cost
# tens of ms, before "thousands" of them).

ENABLE_MARKET_TREND_SIGNALS = True
# How many days back to compare when computing market inventory momentum.
# Shorter than OPPONENT_TREND_WINDOW_DAYS on purpose — market price impact
# from a sell-off is immediate, not something that needs 5 days to trust.
MARKET_TREND_WINDOW_DAYS = 3
# Momentum is normalized to units of each resource's own MARKET_PARAMS "T"
# per day (T = that resource's calibrated production-capacity throughput,
# README "Price Function") so a "big move" means the same thing across
# differently-scaled resources (e.g. wheat's T=400 vs strawberry's T=100).
# This coefficient converts normalized momentum into a crop-score discount
# divisor, same mechanism as OPPONENT_GROWTH_PENALTY but driven by the
# market's OWN realized inventory trend (ground truth: captures both
# players' selling AND town consumption in one number) rather than
# inferring future supply from the opponent's visible tile count alone —
# catches cases tile-tracking misses entirely, e.g. an opponent who already
# harvested-and-dumped and moved their tiles on to a new crop, where the
# price-crash from that dump is still working through the market.
MARKET_TREND_SURGE_PENALTY = 3.0
# Same normalized-momentum threshold, but gates an ADDITIONAL sell-side
# reaction: once a resource's inventory is rising this fast, shrink our own
# hold floor for it too — the crash is already underway, waiting for a
# recovery is a worse bet than usual.
MARKET_TREND_SURGE_THRESHOLD = 0.05
MARKET_TREND_SELL_DISCOUNT = 0.6

# Real leaderboard replays (NOTES.md "v9") repeatedly showed opponents who
# NEVER expand past their starting quadrant beating us decisively — our own
# expansion trigger only ever looked at OUR utilization, never at whether
# the strategy the opponent is visibly committing to (stay lean, single-
# quadrant) is working for them. When the opponent hasn't expanded yet,
# require a stricter utilization bar before we do either; once they HAVE
# expanded, the normal EXPANSION_UTILIZATION_THRESHOLD applies (no reason
# for extra caution if the opponent's own decision already validated that
# expanding is viable in this particular matchup).
ENABLE_OPPONENT_EXPANSION_MIRROR = True
OPPONENT_EXPANSION_MIRROR_THRESHOLD = 0.85

# --- v14: multi-expert regime switching (orchestrator) --------------------
# The "economist" (portfolio targets/expansion/hire, _decide_* functions
# below) and "speculator" (opponent/market trend signals, v10/v11 above)
# roles already existed as separate concerns inside strategy.py. This adds
# an explicit ORCHESTRATOR decision on top of both: classify our standing
# each day (ahead/neutral/behind) and let that bias risk posture, instead of
# running one fixed posture the whole game.
#
# Rationale (SDD §1.1, confirmed via kaggle-agent-SDD.md line ~32): the
# competition's actual scoring is an Elo-like skill rating where "coin
# margin does not affect rating change at all — only win/lose/tie matters."
# That means the whole prior tuning history (CROP_TARGET_WEIGHT, etc.) was
# implicitly optimizing money margin, which correlates with winning but
# isn't quite the right target. Rating theory says the optimal posture
# shifts with standing: protect a likely win with LOWER variance (ahead),
# accept HIGHER variance to escape a likely loss (behind) — a moderate loss
# costs the same rating as a huge one, so there's no penalty for swinging
# for it once behind.
ENABLE_REGIME_SWITCHING = True
# Opponent cash is hidden (README), so "ahead/behind" can't compare bank
# balances directly. Proxy: visible economic footprint = sum over each
# side's visible tiles/structures of (YIELD_PER_TILE_PER_DAY x
# PRODUCT_BASE_PRICE) — same units for both sides, uses only what's
# actually visible (README: opponent's farm is fully visible, only their
# shed/inventory is hidden).
REGIME_AHEAD_RATIO = 1.15    # our footprint > opponent's by this ratio -> "ahead"
REGIME_BEHIND_RATIO = 0.87  # our footprint < opponent's by this ratio (~1/1.15) -> "behind"
REGIME_PRESETS = {
    # Ahead: protect the lead. Diversify a bit more (lower concentration
    # variance), hold slightly longer for fuller value, raise the
    # expansion/animal bar rather than lower it — no reason to gamble a
    # likely win to chase a bigger margin the rating won't reward anyway.
    "ahead":   {"concentration_mult": 0.85, "hold_floor_mult": 1.10, "expansion_mult": 1.10, "animal_cash_mult": 0.85},
    # Neutral: exactly today's tuned baseline — every multiplier a no-op.
    "neutral": {"concentration_mult": 1.00, "hold_floor_mult": 1.00, "expansion_mult": 1.00, "animal_cash_mult": 1.00},
    # Behind: worth taking more variance to catch up. Concentrate harder on
    # the top-scoring crop, sell faster for cash to reinvest, lower the
    # expansion/animal bar to grow capacity more eagerly.
    "behind":  {"concentration_mult": 1.20, "hold_floor_mult": 0.80, "expansion_mult": 0.90, "animal_cash_mult": 1.20},
}

# ==== market_model.py ====
"""MarketModel: price-curve math, sell-timing helpers (SDD §3.4, M3).

Implements the README "Price Function":
    price(inv) = base + sign * amp * f(|inv - I0|)
    sign = +1 if inv < I0 (scarcity -> price up), -1 if inv > I0 (glut -> price down)
    amp  = target * base / f(T)   (derived, not stored)
    f    in {linear, sq, sqrt, log}   (log uses ln(1+x))
Floored at $1, rounded to the nearest dollar.
"""




def _shape(func_name: str, x: float) -> float:
    if func_name == "linear":
        return x
    if func_name == "sq":
        return x * x
    if func_name == "sqrt":
        return math.sqrt(x)
    if func_name == "log":
        return math.log1p(x)
    if func_name == "log10":
        return math.log10(1 + x)
    raise ValueError(f"unknown shape function: {func_name}")


def price_at(resource: str, inventory: int) -> int:
    """Price for the next unit sold/bought at the given market inventory level."""
    params = MARKET_PARAMS[resource]
    base, i0, t = params["base"], params["I0"], params["T"]
    diff = inventory - i0
    if diff == 0:
        return base

    if diff < 0:
        sign, func, target = 1, params["below_func"], params["below_target"]
    else:
        sign, func, target = -1, params["above_func"], params["above_target"]

    denom = _shape(func, t)
    amp = (target * base / denom) if denom else 0.0
    raw = base + sign * amp * _shape(func, abs(diff))
    return max(1, round(raw))


def current_price(resource: str, state) -> int:
    """Price from live obs if available, else derive it from inventory."""
    if resource in state.market_prices:
        return state.market_prices[resource]
    inv = state.market_inventory.get(resource, MARKET_PARAMS[resource]["I0"])
    return price_at(resource, inv)


def max_sell_before_floor(resource: str, inventory: int, floor_price: float, max_units: int = MAX_SELL_SIMULATION_UNITS) -> int:
    """How many units can be sold one-at-a-time (each sale nudges inventory up
    and price down, per README "Selling inventory to the market") before the
    per-unit price drops below `floor_price`. Caps the walk at max_units —
    plenty for any single-turn order given maxMarketOrdersPerTurn."""
    inv = inventory
    count = 0
    for _ in range(max_units):
        p = price_at(resource, inv)
        if p < floor_price:
            break
        count += 1
        inv += 1
    return count

# ==== state.py ====
"""StateParser: converts raw `obs` dict into typed GameState. Single source of
truth — no other module should touch raw obs directly (SDD §3.1)."""



@dataclass
class PlantTile:
    crop: str
    planted_day: int
    watered_today: bool
    consecutive_unwatered: int
    yield_units: int
    max_lifespan_step: int
    fertilized_until_day: int


@dataclass
class WeedTile:
    pass


@dataclass
class StructureTile:
    kind: str  # "COOP" | "PASTURE"
    animal: Optional[str]
    placed_day: int
    yield_units: int
    fed_today: bool
    consecutive_unfed: int
    cared_today: bool
    fertilizer_available: bool
    pending_care_bonus: int


Tile = Optional[object]  # None (empty), "LOCKED", PlantTile, WeedTile, StructureTile


def parse_tile(raw) -> Tile:
    if raw is None or raw == "LOCKED":
        return raw
    kind = raw.get("kind")
    if kind == "PLANT":
        return PlantTile(
            crop=raw["crop"],
            planted_day=raw["planted_day"],
            watered_today=raw["watered_today"],
            consecutive_unwatered=raw["consecutive_unwatered"],
            yield_units=raw["yield_units"],
            max_lifespan_step=raw["max_lifespan_step"],
            fertilized_until_day=raw["fertilized_until_day"],
        )
    if kind == "WEED":
        return WeedTile()
    if kind in ("COOP", "PASTURE"):
        return StructureTile(
            kind=kind,
            animal=raw.get("animal"),
            placed_day=raw.get("placed_day", 0),
            yield_units=raw.get("yield_units", 0),
            fed_today=raw.get("fed_today", False),
            consecutive_unfed=raw.get("consecutive_unfed", 0),
            cared_today=raw.get("cared_today", False),
            fertilizer_available=raw.get("fertilizer_available", False),
            pending_care_bonus=raw.get("pending_care_bonus", 0),
        )
    return raw


@dataclass
class Farm:
    money: float
    tiles: list  # tiles[y][x], parsed
    farmer: tuple
    hands: list
    unlocked_quadrants: list
    hires_today: int


@dataclass
class GameState:
    player: int
    step: int
    day: int
    hour: int
    my_farm: Farm
    opp_farm: Farm
    shed: dict
    seeds: dict
    inventories: list
    market_inventory: dict
    market_prices: dict
    unlocked_shops: list

    def tile_at(self, x: int, y: int):
        return self.my_farm.tiles[y][x]

    def is_shed_adjacent(self, pos: tuple) -> bool:
        from .config import SHED_CENTER_TILES
        return tuple(pos) in SHED_CENTER_TILES


def _parse_farm(raw_farm) -> Farm:
    tiles = [[parse_tile(cell) for cell in row] for row in raw_farm["tiles"]]
    return Farm(
        money=raw_farm["money"],
        tiles=tiles,
        farmer=tuple(raw_farm["farmer"]),
        hands=[tuple(h) for h in raw_farm.get("hands", [])],
        unlocked_quadrants=list(raw_farm.get("unlocked_quadrants", [])),
        hires_today=raw_farm.get("hires_today", 0),
    )


class StateParser:
    @staticmethod
    def parse(obs: dict) -> GameState:
        player = obs["player"]
        farms = obs["farms"]
        my_farm = _parse_farm(farms[player])
        opp_farm = _parse_farm(farms[1 - player])
        private = obs.get("private", {})
        market = obs.get("market", {})
        town = obs.get("town", {})
        return GameState(
            player=player,
            step=obs.get("step", 0),
            day=obs["day"],
            hour=obs["hour"],
            my_farm=my_farm,
            opp_farm=opp_farm,
            shed=dict(private.get("shed", {})),
            seeds=dict(private.get("seeds", {})),
            inventories=[dict(i) for i in private.get("inventories", [])],
            market_inventory=dict(market.get("inventory", {})),
            market_prices=dict(market.get("prices", {})),
            unlocked_shops=list(town.get("unlocked_shops", [])),
        )

# ==== strategy.py ====
"""StrategyAgent: economic/strategic layer (SDD §3.2, §5).

M3 adds real sell-policy hold thresholds (§5.4, sourced from MarketModel via
farm_ops) — this module just supplies the per-resource floors from config.
M4 adds animal portfolio decisions (§5.5): which animals to buy this phase
and how many coop/pasture structures are needed to house them.
"""




@dataclass
class DayPlan:
    day: int
    phase: str
    crop_targets: dict          # {crop: desired_tile_count}, only crops with target > 0 get new plantings
    animal_targets: dict        # {animal: desired_total_owned}, only animals with target > 0 get bought
    structure_targets: dict     # {"COOP": n, "PASTURE": m} derived from animal_targets
    hire_count: int
    buy_land: bool
    sell_thresholds: dict       # {resource: hold_floor_pct}
    regime: str = "neutral"     # v14 orchestrator's standing classification for this day
    land_cost: float = 0.0      # v16: cost of the pending BUY_LAND, so farm_ops can budget it


def phase_for_day(day: int) -> str:
    if day <= PHASE_DAY_BOUNDARIES["early_end"]:
        return "early"
    if day <= PHASE_DAY_BOUNDARIES["buildout_end"]:
        return "buildout"
    if day <= PHASE_DAY_BOUNDARIES["scale_end"]:
        return "scale"
    return "endgame"


def fib_cost(n: int) -> int:
    a, b = 1, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def _count_unlocked_tiles(farm) -> int:
    return sum(1 for row in farm.tiles for cell in row if cell != "LOCKED")


def _count_utilized_tiles(farm) -> int:
    # A weed is wasted space, not utilization — counting it as "utilized"
    # would make an already-overwhelmed, weed-infested farm look MORE
    # eligible for expansion instead of less (found via a real leaderboard
    # replay: our farm hit 23/75 weeds after expanding while "utilization"
    # stayed high enough to keep triggering the next BUY_LAND).
    return sum(
        1 for row in farm.tiles for cell in row
        if isinstance(cell, (PlantTile, StructureTile))
    )


def _count_weeds(farm) -> int:
    return sum(1 for row in farm.tiles for cell in row if isinstance(cell, WeedTile))


def _next_land_to_buy(farm):
    for quadrant in LAND_PURCHASE_ORDER:
        if quadrant not in farm.unlocked_quadrants:
            return quadrant
    return None


def _eligible_crops_for_phase(phase: str, remaining_days: int) -> list:
    pool = PHASE_CROP_POOL[phase]
    if phase != "endgame":
        # Endgame check applies at every phase too: don't start a crop that
        # can't reach first yield before the season ends (SDD §5.1).
        return [c for c in pool if remaining_days >= CROP_DATA[c]["first_yield_day"]]
    # Explicit endgame pool is empty by config; recover any crop that can
    # still fit an entire quick cycle in the remaining days.
    return [
        c for c in CROP_PRIORITY_ORDER
        if remaining_days >= CROP_DATA[c]["first_yield_day"]
    ]


# === SPECULATOR EXPERT: opponent & market trend signals (v10/v11), plus
# the v14 orchestrator's standing classifier below. Reads what's visible
# about the opponent and the shared market and turns it into risk signals
# for the economist to react to — never decides WHAT to plant/buy/expand
# itself, only how cautiously or aggressively to do it. ===================


def _opponent_crop_counts(state: GameState) -> dict:
    """Opponent's farm is fully visible (README: "can see the state of the
    opponent's farm", only their shed/inventory is hidden) — count what
    they've planted so crop scoring can react to it."""
    counts = {}
    for row in state.opp_farm.tiles:
        for cell in row:
            if isinstance(cell, PlantTile):
                counts[cell.crop] = counts.get(cell.crop, 0) + 1
    return counts


def _opponent_resource_counts(state: GameState) -> dict:
    """Crop counts plus animal counts, both keyed by PRODUCT name (matching
    PRODUCT_BASE_PRICE/YIELD_PER_TILE_PER_DAY) rather than crop/animal
    name, so crop scoring, growth tracking, and market-supply forecasting
    can all share one opponent-visibility snapshot. Crop names already ARE
    their own product name; animals map through ANIMAL_DATA."""
    counts = dict(_opponent_crop_counts(state))
    for row in state.opp_farm.tiles:
        for cell in row:
            if isinstance(cell, StructureTile) and cell.animal is not None:
                product = ANIMAL_DATA[cell.animal]["product"]
                counts[product] = counts.get(product, 0) + 1
    return counts


def _opponent_growth_rate(history: dict, day: int, resource: str, window: int) -> float:
    """Tiles/day change in the opponent's visible resource count over the
    last `window` days, from a {day: {resource: count}} history dict this
    StrategyAgent instance has been accumulating (see plan()). Returns 0.0
    if there's no data far back enough yet (early game, or a fresh
    instance in a unit test with no accumulated history) — growth-rate
    scoring degrades gracefully to the pre-v10 behavior in that case."""
    past_day = day - window
    if past_day not in history or day not in history:
        return 0.0
    past_count = history[past_day].get(resource, 0)
    now_count = history[day].get(resource, 0)
    return (now_count - past_count) / window


def _market_trend_momentum(history: dict, day: int, resource: str, window: int) -> float:
    """Day-over-day change in the market's ACTUAL inventory for `resource`,
    normalized to units of that resource's own MARKET_PARAMS "T" per day
    (so "big" means the same thing whether it's wheat, T=400, or
    strawberry, T=100). Ground truth, not a proxy: reflects both players'
    selling AND town consumption in one number — catches things opponent-
    tile tracking misses entirely, e.g. an opponent who already
    harvested-and-dumped and moved their tiles on to something else, where
    the price-crash from that dump is still working through the market."""
    past_day = day - window
    if past_day not in history or day not in history:
        return 0.0
    past_inv = history[past_day].get(resource)
    now_inv = history[day].get(resource)
    if past_inv is None or now_inv is None:
        return 0.0
    t = MARKET_PARAMS.get(resource, {}).get("T", 1)
    return (now_inv - past_inv) / window / t


def _economic_footprint(state: GameState, side: str) -> float:
    """Visible daily production-VALUE estimate for `side` ('my' or 'opp'):
    sum over every visible crop tile / occupied structure of its own
    YIELD_PER_TILE_PER_DAY x PRODUCT_BASE_PRICE. Same units for both sides
    even though neither player's cash is visible to the other (README: the
    opponent's farm IS fully visible, only their shed/inventory is hidden)
    — this is the v14 orchestrator's only available "who's ahead" proxy."""
    farm = state.my_farm if side == "my" else state.opp_farm
    total = 0.0
    for row in farm.tiles:
        for cell in row:
            if isinstance(cell, PlantTile):
                total += YIELD_PER_TILE_PER_DAY.get(cell.crop, 0.0) * PRODUCT_BASE_PRICE.get(cell.crop, 0.0)
            elif isinstance(cell, StructureTile) and cell.animal is not None:
                product = ANIMAL_DATA[cell.animal]["product"]
                total += YIELD_PER_TILE_PER_DAY.get(product, 0.0) * PRODUCT_BASE_PRICE.get(product, 0.0)
    return total


def _classify_regime(state: GameState) -> str:
    """v14 orchestrator signal: classify our standing from the visible
    footprint proxy above. Uses a ratio BAND rather than a hard >/< split
    so the regime doesn't flip-flop on small day-to-day noise near parity
    — only a clearly lopsided footprint moves off "neutral"."""
    our_footprint = _economic_footprint(state, "my")
    opp_footprint = _economic_footprint(state, "opp")
    # Either side at zero footprint is a data-insufficiency case (very
    # early game, or an opponent that genuinely hasn't planted anything
    # yet), not real evidence of a lead — treating "opponent has 0 visible
    # tiles" as automatic "ahead" would bias the very early game on noise
    # alone. Wait for both sides to have SOME visible footprint before
    # trusting the ratio.
    if our_footprint <= 0 or opp_footprint <= 0:
        return "neutral"
    ratio = our_footprint / opp_footprint
    if ratio >= REGIME_AHEAD_RATIO:
        return "ahead"
    if ratio <= REGIME_BEHIND_RATIO:
        return "behind"
    return "neutral"


def _score_crop(crop: str, opponent_counts: dict, opponent_growth: dict, market_momentum: dict, price_ratio: float = 1.0) -> float:
    info = CROP_DATA[crop]
    # Expected profit per tile-day per action-cost (SDD §5.5), approximated
    # from the Object Types table: (base_price - seed_cost) amortized over
    # time-to-first-yield, favoring fast capital recycling. Biased by
    # CROP_TARGET_WEIGHT — this raw formula treats every crop as a one-shot
    # payout and badly undervalues ongoing earners like STRAWBERRY (4
    # scheduled cycles, not 1); the weight corrects for that using a real
    # top-opponent's observed allocation as ground truth (see config.py).
    score = (info["base_price"] - info["seed_cost"]) / max(info["first_yield_day"], 1)
    score *= CROP_TARGET_WEIGHT.get(crop, 1.0)

    # SDD §5.5: "if opponent is flooding a resource, expect price crash
    # there — diversify away from it." Both players sell into the SAME
    # shared market (README "Market" — one dynamic market, not per-player),
    # so an opponent already planting heavily into a crop is a leading
    # indicator of oversupply by the time our own harvest lands. Each
    # opponent tile of that crop discounts our score for it a bit.
    opp_n = opponent_counts.get(crop, 0)
    if opp_n:
        score /= 1 + opp_n * OPPONENT_FLOOD_PENALTY

    # v10: an opponent rapidly SCALING UP a crop is a bigger threat than
    # one sitting on a large but static count — their growth has more room
    # to compound before our harvest lands. Only ever discounts further
    # (a shrinking/negative rate contributes nothing), and only engages
    # once there's enough accumulated history to measure a rate at all.
    growth = opponent_growth.get(crop, 0.0)
    if growth > 0:
        score /= 1 + growth * OPPONENT_GROWTH_PENALTY

    # v11: the market's OWN realized inventory trend, independent of (and
    # complementary to) the opponent-tile-based signals above — inventory
    # rising fast means the price is already heading toward the floor
    # regardless of who's causing it, so redirecting new seed budget away
    # from it is justified either way (SDD §5.5-adjacent, but grounded in
    # actual market state rather than an opponent-visibility proxy).
    momentum = market_momentum.get(crop, 0.0)
    if momentum > 0:
        score /= 1 + momentum * MARKET_TREND_SURGE_PENALTY

    # v29 (continued): direct realized-price backstop for the proxies
    # above — see MARKET_PRICE_CRASH_THRESHOLD's config.py comment for the
    # real-match evidence (opponent-visibility signals faded to zero once
    # the opponent abandoned a crashed crop, but the crash itself hadn't
    # recovered). Only engages once price has fallen deeply below the
    # threshold; scales continuously down to near-zero as price approaches
    # 0, and is a strict no-op at or above the threshold.
    if price_ratio < MARKET_PRICE_CRASH_THRESHOLD:
        score *= max(0.0, price_ratio) / MARKET_PRICE_CRASH_THRESHOLD
    return score


# === ECONOMIST EXPERT: portfolio planning — crop/animal targets, land
# expansion, hiring. Decides WHAT to grow and how much capacity to run;
# takes the speculator's risk signals as inputs but never computes them
# itself. Every function below optionally takes a regime multiplier (v14)
# from the orchestrator's REGIME_PRESETS, defaulting to 1.0 (no-op) so
# regime-switching is purely additive over the pre-v14 behavior. ==========


def _decide_crop_targets(state: GameState, phase: str, remaining_days: int, opponent_growth: dict, market_momentum: dict, concentration_mult: float = 1.0) -> dict:
    eligible = _eligible_crops_for_phase(phase, remaining_days)
    unlocked_tiles = _count_unlocked_tiles(state.my_farm)
    if not eligible or unlocked_tiles == 0:
        return {}

    opponent_counts = _opponent_crop_counts(state)
    # v29 (continued): realized live price / base_price per eligible crop —
    # see MARKET_PRICE_CRASH_THRESHOLD's config.py comment.
    price_ratios = {c: current_price(c, state) / CROP_DATA[c]["base_price"] for c in eligible}
    # Proportional allocation by score, not equal-shares-by-rank: a crop
    # scoring 2x another should get roughly 2x the tiles, not just "picked
    # first" for a +1 remainder tile. Every score is clamped to a small
    # positive floor so a crop that scores 0 (or negative, from a heavy
    # opponent-flood discount) still gets some minimal presence rather than
    # vanishing outright.
    raw_scores = {
        c: max(0.01, _score_crop(c, opponent_counts, opponent_growth, market_momentum, price_ratios[c]))
        for c in eligible
    }
    # v14: concentration_mult sharpens (>1, "behind" preset) or flattens
    # (<1, "ahead" preset) the allocation spread via a monotonic power
    # transform — preserves crop RANKING exactly, only changes how
    # lopsided the tile split is, so this composes cleanly with every
    # existing scoring signal above instead of overriding it. Normalized
    # by the max raw score first so the transform is scale-invariant —
    # _score_crop's absolute units vary a lot by context (a heavily
    # opponent-flood-discounted score can be a tiny fraction vs a healthy
    # one), and exponentiating un-normalized values would distort small
    # scores far more aggressively than large ones for no strategic reason.
    if concentration_mult != 1.0:
        max_score = max(raw_scores.values())
        scores = {c: (v / max_score) ** concentration_mult for c, v in raw_scores.items()}
    else:
        scores = raw_scores
    total_score = sum(scores.values())
    ranked = sorted(eligible, key=lambda c: scores[c], reverse=True)

    targets = {}
    allocated = 0
    for i, crop in enumerate(ranked):
        if i == len(ranked) - 1:
            targets[crop] = max(0, unlocked_tiles - allocated)  # remainder goes to the last (lowest-scoring)
        else:
            share = round(unlocked_tiles * scores[crop] / total_score)
            targets[crop] = share
            allocated += share

    # v15: throttle MELON's EARLY-phase tile share, but ONLY while cash is
    # actually tight — found via a "pass"-baseline seed sweep (NOTES.md
    # "v15") that v13's fix (adding MELON to PHASE_CROP_POOL["early"] for
    # a first-mover pricing edge against melon-rushing opponents) had a
    # severe, previously-uncaught side effect: MELON's CROP_TARGET_WEIGHT
    # =3.0 dominance claimed ~80% of early tile allocation (20/25),
    # crowding WHEAT/CARROT down to a handful of tiles each — starving the
    # ONLY fast-cash income (first yield day 2) available before melon's
    # own day-10 payoff. 7/10 seeds crashed into a permanent cash-crunch/
    # weed spiral even against "pass" (a totally passive, non-competing
    # opponent). A FLAT cap (regardless of cash) fixed that completely but
    # also cost the entire v13 first-mover win against `melon_focus_agent`
    # (10/10 -> 0/10) — that matchup's cash stays healthy throughout, so
    # an unconditional cap was solving a problem that specific matchup
    # never had. Gating on `EARLY_PHASE_MELON_CASH_RESERVE` instead: full
    # melon commitment proceeds whenever cash is healthy (preserving the
    # first-mover win), and only throttles back — freeing tiles to WHEAT,
    # not proportionally to every early crop, since WHEAT is specifically
    # the fast-cash crop this is protecting — when a real crunch is
    # actually developing.
    if (
        phase == "early"
        and state.my_farm.money < EARLY_PHASE_MELON_CASH_RESERVE
        and "MELON" in targets
        and targets["MELON"] > EARLY_PHASE_MELON_TILE_CAP
    ):
        freed = targets["MELON"] - EARLY_PHASE_MELON_TILE_CAP
        targets["MELON"] = EARLY_PHASE_MELON_TILE_CAP
        targets["WHEAT"] = targets.get("WHEAT", 0) + freed
    return targets


def _decide_land_expansion(state: GameState, remaining_days: int, expansion_mult: float = 1.0, last_expansion_day: int = None) -> bool:
    farm = state.my_farm
    next_land = _next_land_to_buy(farm)
    if next_land is None or remaining_days < MIN_DAYS_REMAINING_FOR_EXPANSION:
        return False
    if next_land == "NE" and state.day < MIN_DAY_FOR_FIRST_EXPANSION:
        return False
    # v16: cooldown since the LAST expansion (any quadrant, not just the
    # first) — see MIN_DAYS_BETWEEN_EXPANSIONS's config.py comment for
    # the real-match failure this fixes (buying 3 quadrants in ~5 days
    # left most of the new land empty for the rest of the game).
    if last_expansion_day is not None and state.day - last_expansion_day < MIN_DAYS_BETWEEN_EXPANSIONS:
        return False
    # v18: don't buy land we could never realistically staff. Max
    # sustainable coverage = (1 farmer + max_hires) x capacity_per_unit,
    # buffered — see EXPANSION_CAPACITY_BUFFER's config.py comment for
    # the real-match evidence (55-85% of land sitting empty at game end
    # even with the pacing cooldown alone).
    max_coverable_tiles = (1 + HIRE_TRIGGER_LOGIC["max_hires"]) * HIRE_TRIGGER_LOGIC["capacity_per_unit"] * EXPANSION_CAPACITY_BUFFER
    projected_tiles = _count_unlocked_tiles(farm) + 25  # next quadrant is always 25 tiles
    if projected_tiles > max_coverable_tiles:
        return False
    unlocked = _count_unlocked_tiles(farm)
    utilized = _count_utilized_tiles(farm)
    utilization = utilized / unlocked if unlocked else 0.0
    cost = LAND_COSTS[next_land]

    # Weeds are direct evidence we can't keep up with the land we already
    # have — expanding further would only spread unit-turns thinner and
    # compound the backlog. Found via a real leaderboard replay where our
    # farm hit 23/75 (31%) weeds after over-expanding while a
    # single-quadrant opponent with zero weeds tripled our money.
    weed_ratio = _count_weeds(farm) / unlocked if unlocked else 0.0
    if weed_ratio > MAX_WEED_RATIO_FOR_EXPANSION:
        return False

    # v11: real leaderboard replays repeatedly showed opponents who NEVER
    # expand past their starting quadrant beating us decisively — a signal
    # our own utilization-only trigger never looked at. If the opponent
    # hasn't committed to expanding either, hold ourselves to a stricter
    # bar; once they HAVE, their own decision already validated that
    # expanding is viable in this particular matchup, so the normal bar
    # applies with no extra caution.
    required_utilization = EXPANSION_UTILIZATION_THRESHOLD
    if ENABLE_OPPONENT_EXPANSION_MIRROR and len(state.opp_farm.unlocked_quadrants) <= 1:
        required_utilization = OPPONENT_EXPANSION_MIRROR_THRESHOLD
    # v14: >1.0 (ahead) raises the bar — no reason to gamble a likely win
    # on more land to expand a margin the rating won't reward. <1.0
    # (behind) lowers it — worth growing capacity faster to catch up.
    required_utilization *= expansion_mult

    return utilization >= required_utilization and farm.money >= cost * 1.2


def _eligible_animals_for_phase(phase: str, remaining_days: int) -> dict:
    caps = PHASE_ANIMAL_CAP[phase]
    # +2 buffer days: 1 to build the structure, 1 to actually collect the
    # first yield rather than have it land right on the last turn.
    return {a: cap for a, cap in caps.items() if remaining_days >= ANIMAL_DATA[a]["first_yield_day"] + 2}


def _existing_animal_count(state: GameState, animal: str) -> int:
    count = state.shed.get(animal, 0)
    for inv in state.inventories:
        count += inv.get(animal, 0)
    for row in state.my_farm.tiles:
        for cell in row:
            if isinstance(cell, StructureTile) and cell.animal == animal:
                count += 1
    return count


def _decide_animal_targets(state: GameState, phase: str, remaining_days: int, cash_mult: float = 1.0, expected_units: int = None) -> dict:
    caps = _eligible_animals_for_phase(phase, remaining_days)
    if not caps:
        return {}

    # Same guard as land expansion, same reason: weeds are direct evidence
    # the farm is already falling behind, and buying MORE animals (more
    # feed demand, more structures competing for tile space) while it's
    # struggling only compounds the problem. A 10-seed sweep caught a real
    # death spiral where continued animal spending during a weed crisis
    # starved the cash needed to recover — this freezes new animal growth
    # (existing owned animals still get fed/maintained normally) until the
    # farm is back under control.
    farm = state.my_farm
    unlocked = _count_unlocked_tiles(farm)
    weed_ratio = _count_weeds(farm) / unlocked if unlocked else 0.0
    if weed_ratio > MAX_WEED_RATIO_FOR_EXPANSION:
        return {a: _existing_animal_count(state, a) for a in caps if _existing_animal_count(state, a) > 0}

    # `target` is a CAP on total ever-owned, not a per-day increment — once
    # reached, shortfall drops to 0 and MarketExecutor stops buying
    # regardless of how much cash is sitting in the bank. Highest $/day
    # product value gets first claim on the day's animal budget — NOT
    # fastest-to-first-yield, which would rank SHEEP (6 days) ahead of COW
    # (8 days) despite COW being the better earner (base_price/interval_days:
    # COW 160/2=$80/day, SHEEP 200/3=$66.7/day) — matches the real
    # top-opponent's observed ~2:1 COW:SHEEP ratio (see config.py).
    # v23: cap total herd growth by unit CARE capacity too, not just cash
    # — see ANIMAL_CAPACITY_PER_UNIT's config.py comment for the real-match
    # loss this fixes (8 COW + 7 SHEEP bought, cash-affordable each day,
    # but only 4 SHEEP ever stayed fed long enough to matter).
    # `expected_units` is threaded in by plan() as the post-hire headcount
    # (hire_count is decided before this call now) since state.my_farm.hands
    # is ALWAYS empty at this point in the turn (hands reset at day boundary,
    # plan() runs at hour==0 before that day's HIRE orders execute) — reading
    # len(state.my_farm.hands) here silently capped every real game's herd at
    # ~1 animal forever, regardless of actual hire_count (found via a v24
    # real-match trace: hands=5 all game, but animal_targets stuck at {'COW': 1}).
    current_units = expected_units if expected_units is not None else 1 + len(state.my_farm.hands)
    total_owned_all_animals = sum(_existing_animal_count(state, a) for a in ANIMAL_DATA)
    herd_room = max(0, current_units * ANIMAL_CAPACITY_PER_UNIT - total_owned_all_animals)

    spendable = max(0.0, state.my_farm.money - ANIMAL_CASH_RESERVE) * ANIMAL_CASH_FRACTION * cash_mult
    ranked = sorted(caps, key=lambda a: ANIMAL_DATA[a]["base_price"] / ANIMAL_DATA[a]["interval_days"], reverse=True)
    targets = {}
    for animal in ranked:
        cost = ANIMAL_DATA[animal]["cost"]
        cap = caps[animal]
        owned = _existing_animal_count(state, animal)
        room_wanted = max(0, cap - owned)
        affordable = int(spendable // cost) if cost else 0
        room = min(room_wanted, affordable, math.floor(herd_room))
        herd_room -= room
        spendable -= room * cost
        target = owned + room
        if target > 0:
            targets[animal] = target
    return targets


def _decide_structure_targets(animal_targets: dict) -> dict:
    structure_targets = {"COOP": 0, "PASTURE": 0}
    for animal, target in animal_targets.items():
        structure_targets[ANIMAL_DATA[animal]["structure"]] += target
    return structure_targets


def _opponent_supply_pressure(opponent_counts: dict, opponent_growth: dict) -> dict:
    """Projects each resource's opponent-driven daily market-supply add a
    week out (current visible tile/structure count, plus a week of their
    measured growth trend, times the README yield/tile/day figure) — a
    predictive stand-in for "what will the market look like soon" rather
    than reacting only after the glut has already landed."""
    pressure = {}
    for resource, count in opponent_counts.items():
        yield_rate = YIELD_PER_TILE_PER_DAY.get(resource)
        if yield_rate is None:
            continue
        growth = opponent_growth.get(resource, 0.0)
        projected_count = max(0.0, count + growth * 7)
        pressure[resource] = projected_count * yield_rate
    return pressure


def _decide_hires(state: GameState, crop_targets: dict, phase_capacity_per_unit: float = None) -> int:
    """Returns the desired hire count based on actionable-tile need ALONE —
    NOT pre-limited by a cash-fraction budget here. A real leaderboard
    replay caught why that used to matter: gating the desired count by
    `money x fraction` meant that once an animal-heavy cash crunch drove
    money down to a couple dollars, the fraction of that was below even
    the first hire's $1 cost, and hire_count computed to 0 for 9 STRAIGHT
    days despite dozens of tiles needing attention every one of them —
    hiring was cut off exactly when hands were needed most to dig out.
    Actual affordability is now checked once, against the real live
    per-turn budget, in farm_ops.MarketExecutor.build_orders (which also
    budgets HIRE first, before crop seeds/animals, since hands are the
    foundational capacity everything else depends on).

    v15: an EMPTY tile only counts as actionable if `crop_targets` still
    wants something planted there — an empty tile with nothing left to
    plant (endgame, no crop fits the remaining days) isn't real hiring
    need. An EXISTING unwatered plant always counts regardless of
    crop_targets — it needs saving whether or not we're still planting
    new ones, since losing it to a weed forfeits a harvest we could
    otherwise still sell before the season ends (found via a real-match
    replay, NOTES.md "v15": forcing hire_count to 0 during the old
    liquidation window dropped a 4-quadrant farm to 0 hands and weed
    events exploded 27->44->53 tiles in the final 2 days alone).

    v18 tried counting WeedTiles as actionable too, after a real-replay
    trace found hands silently dropping 4->2 and never recovering despite
    a healthy bank ($18k-26k) — a tile that turns into a weed simply
    disappears from this count, which looked like a perverse incentive
    (more weeds -> formula thinks fewer hands are needed). Reverted after
    validation against melon_focus_agent caught a hard regression (win
    rate 15/15 -> 9/15): counting weeds inflated desired hire counts
    enough to compete with the early seed-buying budget (HIRE is budgeted
    first in farm_ops.MarketExecutor), the same failure mode already
    diagnosed once this session for a different parameter
    (`capacity_per_unit`, see NOTES.md "v17"). The original symptom (hands
    not recovering despite healthy cash) is real and still unexplained —
    just not fixed by this particular lever. See NOTES.md "v18" for the
    full investigation.

    v18 (2nd attempt): a day-by-day trace of that same close loss showed
    the formula ISN'T actually stuck — it recomputes fresh every day and
    consistently lands on the SAME plateau (e.g. ceil(18 tiles / 6
    capacity) = 3 total units for an 18-tile farm), which is a fraction
    short of what's needed to fully prevent the occasional missed
    watering that eventually becomes a weed. This is chronic marginal
    UNDER-provisioning from `capacity_per_unit=6` being a bit optimistic,
    not a stuck-value bug — but tightening it globally (tested in
    isolation, `capacity_per_unit=5` alone) regressed vs
    `melon_focus_agent` (15/15 -> 10/15) for the same reason as before:
    more hires desired means more Fibonacci-cost spend competing with the
    early seed-buying budget, even without touching `max_hires`. Since
    the actual understaffing symptom only showed up well into
    buildout/scale (day 14+, long past the vulnerable early-cash window),
    `phase_capacity_per_unit` lets the caller tighten staffing ONLY once
    that window has passed, leaving early/buildout at the current,
    validated value."""
    farm = state.my_farm
    still_planting = sum(crop_targets.values()) > 0
    actionable_tiles = 0
    for row in farm.tiles:
        for cell in row:
            if cell == "LOCKED":
                continue
            if cell is None:
                if still_planting:
                    actionable_tiles += 1
            elif isinstance(cell, PlantTile) and not cell.watered_today:
                actionable_tiles += 1
            elif isinstance(cell, StructureTile) and cell.animal is not None:
                # v27 (continued): a placed animal needs CARE every day,
                # the same daily-reset cadence as an unwatered plant needing
                # WATER — but this formula only ever counted plant-tile
                # workload, so it was blind to animal-care demand entirely.
                # A real-match trace of 3 blowout losses (0.38x-0.44x, all
                # right after v27's structure fix started actually getting
                # 8-9 animals placed) found hands dropping 5->2 around day
                # 13-16 and staying there for the rest of the game: once the
                # crop portfolio was fully planted and well-watered, this
                # formula's actionable count shrank, so it kept computing a
                # LOWER hire need even though 8-9 newly-placed animals were
                # now competing with crops for the same 2 hands' turns every
                # day — the exact "hands not recovering despite healthy
                # cash" symptom flagged as real-but-unexplained back in v18
                # (see this function's docstring). Counting each placed
                # animal as one actionable unit closes that blind spot.
                actionable_tiles += 1
    current_units = 1 + len(farm.hands)
    capacity = phase_capacity_per_unit if phase_capacity_per_unit is not None else HIRE_TRIGGER_LOGIC["capacity_per_unit"]
    needed_units = max(1, math.ceil(actionable_tiles / capacity)) if actionable_tiles else 1
    to_hire = max(0, needed_units - current_units)
    return min(to_hire, HIRE_TRIGGER_LOGIC["max_hires"])


# === ORCHESTRATOR: StrategyAgent.plan() below combines the economist's
# portfolio targets with the speculator's opponent/market signals AND (v14)
# the standing classification into one DayPlan for the turn. The third
# "expert" role, agriculture (tactical unit scheduling — who walks where and
# does what this turn), lives in farm_ops.FarmOpsOrchestrator; it only
# consumes the DayPlan this orchestrator produces and never feeds back into
# it, so it isn't wired in here. ============================================


class StrategyAgent:
    def __init__(self):
        # v10 opponent-trend tracking: {day: {resource: count}}, accumulated
        # across this instance's lifetime. agent.py keeps one StrategyAgent
        # per episode (module-level, persists across turns — SDD §7), so
        # this naturally builds up a real history over a game. A freshly
        # constructed instance (e.g. in a unit test calling
        # StrategyAgent().plan(state) once) simply has no history yet, and
        # every growth-rate lookup degrades to 0.0 (pre-v10 behavior).
        self._opp_history = {}
        # v11: same pattern, but for the market's own realized inventory
        # per resource — {day: {resource: inventory}}.
        self._market_history = {}
        # v16: tracks the day of our own most recent land purchase, so
        # _decide_land_expansion can enforce MIN_DAYS_BETWEEN_EXPANSIONS.
        # `unlocked_quadrants` alone doesn't carry a purchase day, so this
        # is detected by watching the count change turn to turn.
        self._last_expansion_day = None
        self._last_quadrant_count = None

    def plan(self, state: GameState) -> DayPlan:
        phase = phase_for_day(state.day)
        remaining_days = TOTAL_DAYS - state.day

        quadrant_count = len(state.my_farm.unlocked_quadrants)
        if self._last_quadrant_count is not None and quadrant_count > self._last_quadrant_count:
            self._last_expansion_day = state.day
        self._last_quadrant_count = quadrant_count

        opponent_growth = {}
        supply_pressure = {}
        if ENABLE_OPPONENT_TREND_TRACKING:
            self._opp_history[state.day] = _opponent_resource_counts(state)
            resources = self._opp_history[state.day]
            opponent_growth = {
                r: _opponent_growth_rate(self._opp_history, state.day, r, OPPONENT_TREND_WINDOW_DAYS)
                for r in resources
            }
            if ENABLE_SUPPLY_PRESSURE_ADJUSTMENT:
                supply_pressure = _opponent_supply_pressure(resources, opponent_growth)

        market_momentum = {}
        if ENABLE_MARKET_TREND_SIGNALS:
            self._market_history[state.day] = dict(state.market_inventory)
            market_momentum = {
                r: _market_trend_momentum(self._market_history, state.day, r, MARKET_TREND_WINDOW_DAYS)
                for r in self._market_history[state.day]
            }

        # v14 orchestrator step: classify standing, pick the matching preset.
        # ENABLE_REGIME_SWITCHING=False (or an unrecognized regime) falls
        # back to "neutral", whose multipliers are all no-ops — the entire
        # feature degrades cleanly to pre-v14 behavior when disabled, same
        # pattern as every other flag in config.py.
        regime = _classify_regime(state) if ENABLE_REGIME_SWITCHING else "neutral"
        preset = REGIME_PRESETS.get(regime, REGIME_PRESETS["neutral"])

        crop_targets = _decide_crop_targets(
            state, phase, remaining_days, opponent_growth, market_momentum,
            concentration_mult=preset["concentration_mult"],
        )
        buy_land = False if phase == "endgame" else _decide_land_expansion(
            state, remaining_days, expansion_mult=preset["expansion_mult"],
            last_expansion_day=self._last_expansion_day,
        )
        # v16: found via a real-match replay analysis (NOTES.md "v16") —
        # farm_ops.MarketExecutor's shared budget never deducted BUY_LAND's
        # real cost, so same-turn animal orders queued right after it were
        # computed against a stale, pre-purchase budget. The game processes
        # orders sequentially and stops once money actually runs out
        # (README), so an overcommitted animal order could get silently
        # truncated by the ENGINE rather than by our own budget check —
        # observed directly: 5 PASTURE structures built but only 2 COW
        # ever purchased to fill them. land_cost lets farm_ops deduct it
        # like every other spend.
        land_cost = LAND_COSTS[_next_land_to_buy(state.my_farm)] if buy_land else 0.0

        # v15: hiring stays need-based even during liquidation. The
        # original "no time to recoup a new hand's cost" reasoning only
        # applies to hiring as a NEW INVESTMENT (fair to skip — the
        # LAND/SEED/ANIMAL purchases below still stop), but it doesn't
        # apply to maintaining coverage on a farm that ALREADY exists.
        # Found via a real-match replay (NOTES.md "v15"): hire_count
        # forced to 0 on days 28-29 dropped a 4-quadrant, 100-tile farm to
        # 0 hands (just the farmer), and weed events exploded 27 -> 44 ->
        # 53 tiles in exactly those 2 final days — destroying still-
        # unharvested crops that could otherwise have been sold before the
        # season ended, the opposite of what liquidation is supposed to
        # achieve.
        # v18: a stricter capacity_per_unit only once well past the
        # vulnerable early seed-buying window (see _decide_hires'
        # docstring) — None for early/buildout uses the normal
        # HIRE_TRIGGER_LOGIC value unchanged.
        phase_capacity = TIGHT_HIRE_CAPACITY_PER_UNIT if phase in ("buildout", "scale", "endgame") else None
        hire_count = _decide_hires(state, crop_targets, phase_capacity_per_unit=phase_capacity)

        # v24: animal_targets must be computed AFTER hire_count and given the
        # expected post-hire headcount — state.my_farm.hands is always empty
        # here (hands reset at day boundary, this runs at hour==0 before that
        # day's HIRE orders execute), so reading len(state.my_farm.hands)
        # permanently capped herd growth at ~1 animal regardless of the real
        # hire_count that executes later this same turn (see NOTES.md "v24").
        expected_units = 1 + len(state.my_farm.hands) + hire_count
        animal_targets = _decide_animal_targets(
            state, phase, remaining_days, cash_mult=preset["animal_cash_mult"],
            expected_units=expected_units,
        )
        structure_targets = _decide_structure_targets(animal_targets)

        if remaining_days <= LIQUIDATION_DAYS_REMAINING:
            # Liquidate: ignore hold floors, everything in the shed becomes
            # cash before the season ends rather than being stranded stock.
            sell_thresholds = {resource: 0.0 for resource in PRODUCT_BASE_PRICE}
        else:
            sell_thresholds = {resource: HOLD_FLOOR_PCT.get(resource, 0.0) for resource in PRODUCT_BASE_PRICE}
            # v10: an opponent's visible production trend projecting a glut
            # soon means holding for a price recovery is less likely to pay
            # off — sell into it sooner rather than waiting. Only ever
            # shrinks the floor (more willing to sell), never raises it.
            for resource, pressure in supply_pressure.items():
                if pressure > OPPONENT_SUPPLY_PRESSURE_THRESHOLD and resource in sell_thresholds:
                    sell_thresholds[resource] *= OPPONENT_SUPPLY_PRESSURE_HOLD_DISCOUNT
            # v11: same idea, but from the market's own realized trend
            # rather than a projection off the opponent's visible tiles —
            # independent evidence, applied independently (can compound
            # with the above, which is directionally fine: more evidence
            # of an incoming glut only ever means selling sooner is right).
            for resource, momentum in market_momentum.items():
                if momentum > MARKET_TREND_SURGE_THRESHOLD and resource in sell_thresholds:
                    sell_thresholds[resource] *= MARKET_TREND_SELL_DISCOUNT
            # v14: regime-wide hold-floor bias, layered on top of the two
            # evidence-driven discounts above (>1.0 ahead -> hold a bit
            # longer for fuller value; <1.0 behind -> sell faster to
            # reinvest into catching up).
            for resource in sell_thresholds:
                sell_thresholds[resource] *= preset["hold_floor_mult"]

        return DayPlan(
            day=state.day,
            phase=phase,
            crop_targets=crop_targets,
            animal_targets=animal_targets,
            structure_targets=structure_targets,
            hire_count=hire_count,
            buy_land=buy_land,
            sell_thresholds=sell_thresholds,
            regime=regime,
            land_cost=land_cost,
        )

# ==== farm_ops.py ====
"""FarmOpsOrchestrator: tactical layer, runs every turn (SDD §3.3, §6).

M3 adds market-timing to MarketExecutor: sell orders are sized against
MarketModel's hold floor instead of dumping the whole shed every turn (§5.4).
M4 adds animal husbandry to UnitScheduler: building coops/pastures, placing
purchased animals, feeding, caring, collecting fertilizer, and harvesting
animal product — layered onto the same greedy-scored candidate pool used for
crops (§6), plus a small pre-stage for the "carrying something, go deal with
it" cases that don't fit the tile-exclusive candidate model (return-to-shed,
place-animal, fetch-feed-wheat).
"""



STRUCTURE_OP = {"COOP": "BUILD_COOP", "PASTURE": "BUILD_PASTURE"}


def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def nearest_shed_tile(pos):
    return min(SHED_CENTER_TILES, key=lambda t: manhattan(pos, t))


def step_toward(cur, target):
    dx = target[0] - cur[0]
    dy = target[1] - cur[1]
    if abs(dx) >= abs(dy) and dx != 0:
        return "EAST" if dx > 0 else "WEST"
    if dy != 0:
        return "SOUTH" if dy > 0 else "NORTH"
    return "PASS"


class UnitScheduler:
    """Greedy priority-scored task assignment across farmer + hands (SDD §6)."""

    def __init__(self):
        # v20: persists which unit is currently walking toward which
        # critical-unwatered tile, across turns within an episode (this
        # instance lives for the whole episode, see agent.py) — see the
        # critical-unwatered rescue block in assign() for why.
        self._committed_rescues = {}  # unit_index -> (x, y) tile position

    def assign(self, state: GameState, plan: DayPlan) -> list:
        unit_positions = [state.my_farm.farmer] + list(state.my_farm.hands)
        inventories = state.inventories if state.inventories else [{}] * len(unit_positions)
        unfed_positions = self._find_unfed_animal_tiles(state)
        fertilizable_positions = self._find_fertilizable_tiles(state)

        actions = [None] * len(unit_positions)
        idle_units = []
        # Tracks which unfed animals already have a wheat-carrying unit en
        # route this turn, so N different carriers converge on N different
        # animals instead of all racing to whichever is nearest (which left
        # every animal but one un-rescued when several were critical at
        # once — a real cause of the high escape rate observed via
        # tools/replay_analyze.py's §8.5 breakdown).
        claimed_feed_targets = set()

        for i, pos in enumerate(unit_positions):
            inv = inventories[i] if i < len(inventories) else {}
            action = self._carrying_action(state, pos, inv, unfed_positions, fertilizable_positions, claimed_feed_targets)
            if action is not None:
                actions[i] = action
            else:
                idle_units.append(i)

        if not idle_units:
            return actions

        # An animal that missed yesterday's feeding turns to weeds/escapes
        # tonight if not fed today (README: 2 consecutive misses). A big
        # harvest can out-score a routine FETCH_WHEAT in the generic scorer
        # below, so dedicate one idle unit PER critical animal directly —
        # losing an animal (sunk cost + future production) outweighs a
        # single turn's harvest/plant delay for that many units.
        critical_unfed = [pos for pos, unfed_days in unfed_positions if unfed_days >= 1]
        if critical_unfed and state.shed.get("WHEAT", 0) > 0 and idle_units:
            num_rescuers = min(len(critical_unfed), len(idle_units))
            rescuers = sorted(
                idle_units, key=lambda i: min(manhattan(unit_positions[i], sp) for sp in SHED_CENTER_TILES)
            )[:num_rescuers]
            for rescuer in rescuers:
                pos = unit_positions[rescuer]
                if pos in SHED_CENTER_TILES:
                    actions[rescuer] = ["PICKUP", "WHEAT", 1]
                else:
                    actions[rescuer] = [step_toward(pos, nearest_shed_tile(pos))]
                idle_units.remove(rescuer)

        if not idle_units:
            return actions

        # Same problem, same fix, for plants: a high-value HARVEST candidate
        # (value = base_price x yield_units, uncapped — a ready melon alone
        # scores ~6000) routinely outscores a routine WATER (~500) in the
        # generic scorer below, even though WATER already carries an
        # urgency bonus. Root-caused via a real leaderboard replay + a
        # fixed-seed local trace: a WHEAT tile sat at consecutive_unwatered
        # == 1 for a FULL day with 6 units available and the tile only 2
        # steps from the nearest one — every unit was getting pulled to
        # harvest tasks instead, all day, every turn. Dedicating rescuers
        # here (bypassing the scorer entirely, same as the feed-rescue
        # above) guarantees a plant on the brink of becoming a weed always
        # gets a unit working toward it.
        critical_unwatered = self._find_critical_unwatered_tiles(state)
        # v20: drop any commitment whose tile is no longer critical (either
        # successfully watered, or already lost to a weed) before doing
        # anything else this turn — keeps the dict from accumulating stale
        # entries and ensures only genuinely still-critical commitments
        # get honored below.
        critical_set = set(critical_unwatered)
        self._committed_rescues = {i: t for i, t in self._committed_rescues.items() if t in critical_set}
        # v28: tiles claimed here get walked into `assigned_tiles` below so
        # the generic scorer can't independently re-target the SAME tile
        # with a second unit — found via a real weight-retune test failure
        # (extreme urgency weights made the rescue tile's own WATER
        # candidate outscore even a zero-distance ready HARVEST for OTHER
        # idle units too, since `_build_candidates` has no idea this tile
        # is already claimed): 2 units converging on 1 already-rescued
        # tile while an adjacent ready melon sat unharvested.
        rescued_tiles = set()
        if critical_unwatered and idle_units:
            remaining_tiles = list(critical_unwatered)
            rescuer_pool = list(idle_units)

            # Honor existing commitments FIRST, before any fresh distance
            # optimization — found via a real-replay spatial analysis
            # (NOTES.md "v20") that weeds cluster disproportionately in
            # far corners, and a code audit traced why: this rescue used
            # to re-solve the nearest-pair assignment from scratch EVERY
            # turn, so a unit already 2 turns into walking toward tile A
            # could get reassigned to a newly-appeared, marginally closer
            # tile C — abandoning A's progress and potentially never
            # actually reaching either in time. Committing once a
            # rescue starts (and only dropping it when the tile resolves)
            # guarantees forward progress instead of dithering between
            # targets turn to turn.
            for i in list(rescuer_pool):
                committed_tile = self._committed_rescues.get(i)
                if committed_tile is not None and committed_tile in remaining_tiles:
                    pos = unit_positions[i]
                    actions[i] = ["WATER"] if pos == committed_tile else [step_toward(pos, committed_tile)]
                    rescuer_pool.remove(i)
                    remaining_tiles.remove(committed_tile)
                    idle_units.remove(i)
                    rescued_tiles.add(committed_tile)

            num_rescuers = min(len(remaining_tiles), len(rescuer_pool))
            for _ in range(num_rescuers):
                best = min(
                    ((manhattan(unit_positions[i], t), i, t) for i in rescuer_pool for t in remaining_tiles),
                    key=lambda triple: triple[0],
                )
                _, i, t = best
                pos = unit_positions[i]
                actions[i] = ["WATER"] if pos == t else [step_toward(pos, t)]
                self._committed_rescues[i] = t
                rescuer_pool.remove(i)
                remaining_tiles.remove(t)
                idle_units.remove(i)
                rescued_tiles.add(t)

        if not idle_units:
            return actions

        # v20: TRIED a dedicated rescue here for animals already bought but
        # still sitting in the shed (real-replay analysis kept finding
        # owned-animal counts plateau at 1-4 despite generous caps/cash).
        # REVERTED after a deep-dive trace found a genuine negative side
        # effect: once a unit PICKS UP an animal, `_carrying_action`
        # commits it to a multi-turn carry-and-place trip with NO way to
        # interrupt for a more urgent need — including a critical-unfed
        # animal that turns up mid-carry. Same-seed comparison showed
        # placed-animal count actually DROPPING late-game (4->3->1->1
        # over days 26-29) in a farm that stayed flat at 4 the whole game
        # without this stage — not a placement failure, animals that were
        # ALREADY placed were lost to starvation-escape because a unit
        # that would have been available for feed-rescue was mid-carry-trip
        # instead. Bypassing the scorer for a multi-turn COMMITTED action
        # (unlike the water-rescue stage above, which only takes one
        # WATER/step per call and re-evaluates every turn) is the wrong
        # shape for a dedicated rescue. See NOTES.md "v20" for the full
        # investigation — the animal-execution gap (opponents reach 4-6+,
        # we plateau at 1-4) is still real and unsolved.

        if not idle_units:
            return actions

        candidates, cluster_bonus_by_pos = self._build_candidates(state, plan, unfed_positions, fertilizable_positions)

        pairs = []
        for i in idle_units:
            pos = unit_positions[i]
            for tile_pos, task, urgency, value in candidates:
                dist = manhattan(pos, tile_pos)
                score = (
                    urgency * TASK_SCORE_WEIGHTS["urgency"]
                    + value * TASK_SCORE_WEIGHTS["value"]
                    - dist * TASK_SCORE_WEIGHTS["distance"]
                    + cluster_bonus_by_pos.get(tile_pos, 0.0)
                )
                pairs.append((score, i, tile_pos, task))
        pairs.sort(key=lambda p: p[0], reverse=True)

        assigned_units = set()
        assigned_tiles = set(rescued_tiles)
        # README: if too many units PLANT the same crop in one turn without
        # enough seed for all of them, NONE of those plants land — not just
        # the excess. Cap same-turn immediate PLANT actions (pos == tile_pos)
        # per crop at the seed stock actually on hand; movement-only
        # assignments toward a planting tile don't consume a seed this turn,
        # so they're re-evaluated fresh next turn once seed stock is known.
        planted_this_turn = {}
        for score, i, tile_pos, task in pairs:
            if i in assigned_units or tile_pos in assigned_tiles:
                continue
            pos = unit_positions[i]
            if pos == tile_pos and task[0] == "PLANT":
                crop = task[1]
                seed_stock = state.seeds.get(crop, 0)
                if planted_this_turn.get(crop, 0) >= seed_stock:
                    continue
                planted_this_turn[crop] = planted_this_turn.get(crop, 0) + 1
            if pos == tile_pos:
                actions[i] = self._task_to_action(task)
            else:
                actions[i] = [step_toward(pos, tile_pos)]
            assigned_units.add(i)
            assigned_tiles.add(tile_pos)

        for i in idle_units:
            if actions[i] is None:
                actions[i] = ["PASS"]

        return actions

    def _carrying_action(self, state: GameState, pos, inv: dict, unfed_positions: list, fertilizable_positions: list, claimed_feed_targets: set):
        """Handles the "unit is carrying something, go deal with it" cases
        that don't fit the tile-exclusive candidate model below: an animal
        needs placing on a matching empty structure, a harvested product
        needs dropping at the shed, feed wheat needs delivering to the
        nearest hungry animal, or fertilizer needs delivering to the
        nearest eligible plant. Returns None if the unit is carrying
        nothing and should fall through to the generic candidate pool."""
        if not inv:
            return None

        animal_carried = next((item for item in inv if item in ANIMAL_DATA and inv[item] > 0), None)
        if animal_carried:
            structure_kind = ANIMAL_DATA[animal_carried]["structure"]
            target = self._nearest_empty_structure(state, pos, structure_kind)
            if target is None:
                return ["DROP"] if pos in SHED_CENTER_TILES else [step_toward(pos, nearest_shed_tile(pos))]
            if pos == target:
                return ["PLACE", animal_carried]
            return [step_toward(pos, target)]

        fertilizer_qty = inv.get("FERTILIZER", 0)
        if fertilizer_qty > 0:
            if fertilizable_positions:
                target = min(fertilizable_positions, key=lambda t: manhattan(pos, t))
                if pos == target:
                    return ["FERTILIZE"]
                return [step_toward(pos, target)]
            return ["DROP"] if pos in SHED_CENTER_TILES else [step_toward(pos, nearest_shed_tile(pos))]

        non_wheat_qty = sum(v for k, v in inv.items() if k not in ("WHEAT", "FERTILIZER") and k not in ANIMAL_DATA)
        if non_wheat_qty > 0:
            return ["DROP"] if pos in SHED_CENTER_TILES else [step_toward(pos, nearest_shed_tile(pos))]

        wheat_qty = inv.get("WHEAT", 0)
        if wheat_qty > 0:
            available = [t for t in unfed_positions if t[0] not in claimed_feed_targets]
            if available:
                target = min(available, key=lambda t: manhattan(pos, t[0]))[0]
                claimed_feed_targets.add(target)
                if pos == target:
                    return ["FEED"]
                return [step_toward(pos, target)]
            if unfed_positions:
                # Every unfed animal already has a carrier headed its way
                # this turn — fall back to the nearest one anyway (a second
                # carrier arriving is harmless, unlike leaving one animal
                # completely unclaimed) rather than wastefully returning
                # this wheat to the shed.
                target = min(unfed_positions, key=lambda t: manhattan(pos, t[0]))[0]
                if pos == target:
                    return ["FEED"]
                return [step_toward(pos, target)]
            return ["DROP"] if pos in SHED_CENTER_TILES else [step_toward(pos, nearest_shed_tile(pos))]

        return None

    def _find_unfed_animal_tiles(self, state: GameState) -> list:
        """Returns [(pos, consecutive_unfed), ...] for every occupied,
        unfed structure — consecutive_unfed drives urgency scaling for the
        FETCH_WHEAT candidate (an animal already at risk of escaping should
        outrank routine crop tasks)."""
        positions = []
        for y, row in enumerate(state.my_farm.tiles):
            for x, cell in enumerate(row):
                if isinstance(cell, StructureTile) and cell.animal is not None and not cell.fed_today:
                    positions.append(((x, y), cell.consecutive_unfed))
        return positions

    def _find_critical_unwatered_tiles(self, state: GameState) -> list:
        """Positions of plants that already missed a watering
        (consecutive_unwatered >= 1) and haven't been watered yet today —
        one more miss turns them into a weed tonight (README)."""
        positions = []
        for y, row in enumerate(state.my_farm.tiles):
            for x, cell in enumerate(row):
                if isinstance(cell, PlantTile) and cell.consecutive_unwatered >= 1 and not cell.watered_today:
                    positions.append((x, y))
        return positions

    def _find_fertilizable_tiles(self, state: GameState) -> list:
        """Positions of existing plants that would benefit from FERTILIZE
        right now (README §Harvest Yields): one-time crops inside their
        watering bonus window (starts at ceil(max_yield_day/2)) not already
        fertilized, or any active ongoing crop not already fertilized
        (fertilize+water doubles its scheduled yield, any day)."""
        positions = []
        for y, row in enumerate(state.my_farm.tiles):
            for x, cell in enumerate(row):
                if not isinstance(cell, PlantTile):
                    continue
                if cell.fertilized_until_day >= state.day:
                    continue  # bonus already active
                crop_info = CROP_DATA.get(cell.crop)
                if crop_info is None:
                    continue
                age = state.day - cell.planted_day
                if crop_info["one_time"]:
                    bonus_start = math.ceil(crop_info["max_yield_day"] / 2)
                    if bonus_start <= age <= crop_info["max_yield_day"]:
                        positions.append((x, y))
                else:
                    positions.append((x, y))
        return positions

    def _nearest_empty_structure(self, state: GameState, pos, structure_kind: str):
        candidates = [
            (x, y)
            for y, row in enumerate(state.my_farm.tiles)
            for x, cell in enumerate(row)
            if isinstance(cell, StructureTile) and cell.kind == structure_kind and cell.animal is None
        ]
        if not candidates:
            return None
        return min(candidates, key=lambda t: manhattan(pos, t))

    def _build_candidates(self, state: GameState, plan: DayPlan, unfed_positions: list, fertilizable_positions: list):
        """Watering/harvesting/animal-care apply to any existing plant or
        animal regardless of the current phase's active pool (an old
        planting or animal must still be tended). Only NEW plantings/
        structures are restricted to plan.crop_targets/structure_targets."""
        candidates = []
        empty_tiles = []
        active_crops = [c for c, target in plan.crop_targets.items() if target > 0]
        planted_counts = {c: 0 for c in active_crops}
        structure_counts = {"COOP": 0, "PASTURE": 0}
        empty_structure_counts = {"COOP": 0, "PASTURE": 0}

        tiles = state.my_farm.tiles
        for y, row in enumerate(tiles):
            for x, tile in enumerate(row):
                if tile == "LOCKED":
                    continue
                pos = (x, y)
                if tile is None:
                    empty_tiles.append(pos)
                elif isinstance(tile, PlantTile):
                    crop_info = CROP_DATA.get(tile.crop)
                    if crop_info is None:
                        continue
                    if tile.crop in planted_counts:
                        planted_counts[tile.crop] += 1
                    if not tile.watered_today:
                        urgency = 3 if tile.consecutive_unwatered >= 1 else 1
                        value = crop_info["base_price"] * 0.5
                        candidates.append((pos, ("WATER",), urgency, value))
                    age = state.day - tile.planted_day
                    if age >= crop_info["first_yield_day"] and tile.yield_units > 0:
                        value = crop_info["base_price"] * tile.yield_units
                        candidates.append((pos, ("HARVEST",), 2, value))
                elif isinstance(tile, WeedTile):
                    # v18 tried raising this (urgency 0->1, value 5->40)
                    # after a real-replay trace suggested weeds were
                    # under-prioritized — tournament-style validation
                    # against melon_focus_agent immediately caught the
                    # opposite problem: win rate collapsed 15/15 -> 0/15.
                    # Diverting units to DIG (which only clears space,
                    # earns nothing directly) away from HARVEST/WATER
                    # (which do) is a bad trade against a benchmark that
                    # rewards raw output. Reverted — DIG stays deliberately
                    # low priority; see NOTES.md "v18" for the full
                    # investigation and why this lever doesn't work.
                    candidates.append((pos, ("DIG",), 0, 5))
                elif isinstance(tile, StructureTile):
                    structure_counts[tile.kind] = structure_counts.get(tile.kind, 0) + 1
                    if tile.animal is None:
                        empty_structure_counts[tile.kind] = empty_structure_counts.get(tile.kind, 0) + 1
                    if tile.animal is not None:
                        animal_info = ANIMAL_DATA[tile.animal]
                        if tile.yield_units > 0:
                            value = animal_info["base_price"] * tile.yield_units
                            candidates.append((pos, ("HARVEST",), 2, value))
                        if not tile.cared_today:
                            value = animal_info["base_price"] * 0.3
                            candidates.append((pos, ("CARE",), 1, value))
                        if tile.fertilizer_available:
                            # v15: bumped from urgency=1/0.3x to urgency=2/1.0x
                            # after a real-match replay analysis (NOTES.md
                            # "v15") found a top real opponent earning nearly
                            # HALF their total money from fertilizer sales
                            # ($38,700 of ~$79,500) while we earned $229 in
                            # the same matchup. README: "uncollected
                            # fertilizer does not accumulate" — every animal
                            # makes exactly 1 unit available per day whether
                            # collected or not, so a missed collection is a
                            # PERMANENT loss, not a deferred one like a
                            # routine HARVEST/WATER that just waits for the
                            # next turn. The old 0.3x/urgency=1 weighting
                            # treated it like a low-stakes routine task and
                            # let it lose the generic scorer's tie-break to
                            # nearly everything else on a busy farm.
                            candidates.append((pos, ("COLLECT_FERTILIZER",), 2, PRODUCT_BASE_PRICE["FERTILIZER"]))

        # Purchased animals sit in the shed until a unit fetches them
        # (README: BUY_ANIMAL delivers to the shed, not directly onto a
        # structure) — inject a PICKUP task whenever an empty matching
        # structure is ready, mirroring FETCH_WHEAT below. Once a unit
        # picks one up, _carrying_action (assign()) takes over and walks it
        # to the structure to PLACE.
        for animal, info in ANIMAL_DATA.items():
            if state.shed.get(animal, 0) > 0 and empty_structure_counts.get(info["structure"], 0) > 0:
                # v26: kept comfortably above BUILD_STRUCTURE's value (now
                # scaled to up to the highest housed animal's base_price,
                # 200 for SHEEP/PASTURE) — placing an animal ALREADY bought
                # into a structure that ALREADY exists must always outrank
                # starting a brand new structure for one not yet bought,
                # the same "protect committed spend before chasing more"
                # priority already applied to wheat feed top-ups (v20).
                value = info["base_price"] * 5
                for shed_pos in SHED_CENTER_TILES:
                    candidates.append((shed_pos, ("FETCH_ANIMAL", animal), 1, value))

        # An unfed animal doesn't feed itself: inject a PICKUP WHEAT task at
        # the shed whenever wheat is in stock and something needs feeding,
        # so an empty-handed idle unit has a reason to go get it. Once
        # carried, _carrying_action routes the unit to the animal to FEED.
        if unfed_positions and state.shed.get("WHEAT", 0) > 0:
            urgency = 3 if any(c >= 1 for _, c in unfed_positions) else 1
            value = PRODUCT_BASE_PRICE.get("EGG", 50) * 2
            for shed_pos in SHED_CENTER_TILES:
                candidates.append((shed_pos, ("FETCH_WHEAT",), urgency, value))

        # Same fetch-and-deliver pattern for fertilizer, but kept deliberately
        # LOW priority: missing a fertilize only forfeits a bonus (still get
        # the base yield), unlike missing a WATER (loses the whole plant) or
        # a FEED (loses the whole animal) — those carry urgency multipliers
        # for exactly that reason. An earlier version scaled this value the
        # same way as HARVEST (base_price x yield), which made a melon's
        # ~$750 estimate dominate the scorer outright and starve watering
        # (observed directly: weed events jumped to ~20/episode, win rate
        # vs starter collapsed from 100% to 37.5%). Match WATER's value
        # scale instead so fertilizing competes fairly but never wins over
        # anything that risks losing the plant/animal outright.
        if fertilizable_positions and state.shed.get("FERTILIZER", 0) > 0:
            best_value = 0
            for fx, fy in fertilizable_positions:
                crop_info = CROP_DATA.get(state.my_farm.tiles[fy][fx].crop)
                if crop_info:
                    best_value = max(best_value, crop_info["base_price"] * 0.3)
            for shed_pos in SHED_CENTER_TILES:
                candidates.append((shed_pos, ("FETCH_FERTILIZER",), 1, best_value))

        # New plantings: shortfall computed once from actual planted counts
        # (not decremented per tile) — candidates rebuild fresh every turn
        # from live tile state, so the scorer (§6), not iteration order,
        # decides which unit plants where this turn.
        if ENABLE_MULTI_CROP_PLANTING:
            # v13: every eligible crop gets a PLANT candidate at every empty
            # tile, not just the single best-by-ratio one — SDD §6's known
            # "only one crop plants per turn" limitation otherwise forces a
            # multi-crop portfolio to spend several turns in a row all on
            # the SAME crop before another gets a turn at all. Safe because
            # the seed-overcommit cap in assign() is keyed per-crop.
            for crop in active_crops:
                target = plan.crop_targets[crop]
                if target <= 0 or state.seeds.get(crop, 0) <= 0:
                    continue
                if planted_counts.get(crop, 0) >= target:
                    continue
                crop_info = CROP_DATA[crop]
                value = crop_info["base_price"] - crop_info["seed_cost"]
                for pos in empty_tiles:
                    candidates.append((pos, ("PLANT", crop), 1, value))
        else:
            # Pre-v13 behavior, kept for direct A/B comparison via
            # tools/tournament.py. Ranked by shortfall RATIO
            # (shortfall/target), not raw shortfall count: a crop with a
            # much bigger target (e.g. MELON at 26 tiles) will almost
            # always have a bigger absolute shortfall than one with a
            # smaller target (e.g. STRAWBERRY at 8), so raw-count
            # comparison let MELON win the "which crop plants this turn"
            # slot on nearly every turn regardless of how proportionally
            # starved STRAWBERRY was. Ratio comparison treats "0%
            # fulfilled" the same regardless of the target's absolute size.
            best_crop, best_ratio = None, 0.0
            for crop in active_crops:
                target = plan.crop_targets[crop]
                if target <= 0 or state.seeds.get(crop, 0) <= 0:
                    continue
                shortfall = target - planted_counts.get(crop, 0)
                ratio = shortfall / target
                if ratio > best_ratio:
                    best_ratio, best_crop = ratio, crop
            if best_crop:
                crop_info = CROP_DATA[best_crop]
                value = crop_info["base_price"] - crop_info["seed_cost"]
                for pos in empty_tiles:
                    candidates.append((pos, ("PLANT", best_crop), 1, value))

        # New structures: same shortfall-vs-target pattern, one structure
        # kind per turn so it competes fairly against planting for the same
        # empty tiles via the score, rather than being force-prioritized.
        best_structure, best_structure_shortfall = None, 0
        for kind, target in plan.structure_targets.items():
            shortfall = target - structure_counts.get(kind, 0)
            if shortfall > best_structure_shortfall:
                best_structure_shortfall, best_structure = shortfall, kind

        if best_structure:
            # v26: real-match trace found 8 COW bought (structure_targets
            # correctly set PASTURE:8) but only 2 PASTURE ever got built —
            # the old flat value=80 lost the tile-allocation contest to
            # crop candidates almost every time a tile briefly opened up
            # (e.g. MELON's value is base_price(250)-seed_cost(80)=170,
            # more than double), so 7 of the 8 purchased COW sat unplaced
            # in the shed for the rest of the game, dead cash. Scale value
            # to the structure's actual revenue potential (the highest
            # base_price among animals it houses) instead of an arbitrary
            # flat number, so it competes fairly for scarce empty tiles
            # the same way COLLECT_FERTILIZER/PLANT were re-weighted (v15).
            housed_animals = [a for a, info in ANIMAL_DATA.items() if info["structure"] == best_structure]
            value = max((ANIMAL_DATA[a]["base_price"] for a in housed_animals), default=80)
            op = STRUCTURE_OP[best_structure]
            for pos in empty_tiles:
                candidates.append((pos, (op,), 1, value))

        cluster_bonus_by_pos = self._cluster_bonus(candidates) if ENABLE_CLUSTER_LOOKAHEAD else {}
        return candidates, cluster_bonus_by_pos

    def _cluster_bonus(self, candidates: list) -> dict:
        """Bounded stand-in for real multi-turn search (discussed as an
        alternative to literal minimax, which doesn't fit this game — see
        NOTES.md "v10"): a candidate tile surrounded by other actionable
        tiles lets a unit sent there chain efficiently into the next task
        afterward, instead of finishing an isolated tile and needing a long
        return trip. Returned as a separate {pos: bonus} map added directly
        to the final SCORE in assign() — not baked into the candidate's
        `value` field, which gets multiplied by TASK_SCORE_WEIGHTS["value"]
        (3.8x) and made the bonus wildly overpowering even a single tile of
        distance cost (caught by a unit test: a farmer standing exactly on
        a plantable tile moved away from it just to reach a marginally
        better-clustered one one tile over). Counts unique nearby positions
        that already have their own candidate, not other tasks at the SAME
        position (a tile with both a WATER and HARVEST candidate isn't "2
        neighbors" of itself)."""
        unique_positions = list({pos for pos, _, _, _ in candidates})
        bonus_by_pos = {}
        for pos in unique_positions:
            neighbors = sum(
                1 for other in unique_positions
                if other != pos and manhattan(pos, other) <= CLUSTER_LOOKAHEAD_RADIUS
            )
            bonus_by_pos[pos] = neighbors * CLUSTER_LOOKAHEAD_BONUS_PER_NEIGHBOR
        return bonus_by_pos

    def _task_to_action(self, task):
        op = task[0]
        if op == "PLANT":
            return ["PLANT", task[1]]
        if op == "FETCH_ANIMAL":
            return ["PICKUP", task[1], 1]
        if op == "FETCH_WHEAT":
            return ["PICKUP", "WHEAT", 1]
        if op == "FETCH_FERTILIZER":
            return ["PICKUP", "FERTILIZER", 1]
        return [op]


MAX_MARKET_ORDERS_PER_TURN = 10


class MarketExecutor:
    """Builds the market order list for this turn (SDD §3.3)."""

    def build_orders(self, state: GameState, plan: DayPlan) -> list:
        """Every sub-builder below shares ONE running `budget` (starts at
        `state.my_farm.money`, decremented as each builder commits spend) —
        NOT each independently re-checking the full start-of-turn money.
        Without this, two builders can each see "$3000 available" and both
        request as much as that implies, but the game processes orders in
        list order and actually deducts sequentially: whichever order type
        is queued LAST silently gets starved once real money runs out
        mid-list (README: "If a player runs out of money mid-order, the
        order is stopped"). This is exactly what happened when the animal
        budget (`ANIMAL_CASH_FRACTION`) and crop-seed budget were computed
        independently: animals (listed first) looked affordable on their
        own, crop seeds (checked independently, also against the
        untouched full balance) looked affordable too, and together they
        overcommitted — strawberry/melon seed stock stayed starved for
        days despite `crop_targets` correctly asking for far more.

        Priority order (each stage spends from what the previous left):
        HIRE > crop seeds > wheat feed top-up > land/new animals >
        fertilizer top-up. HIRE is first because it's the foundational
        capacity everything else depends on, and it's cheap (Fibonacci:
        1,1,2,3,5,...) — a real leaderboard replay caught hire_count
        silently computing to 0 for 9 straight days once an animal-heavy
        cash crunch left nothing in the budget for even a single $1 hire,
        while weeds compounded because there was no one left to water
        them. Crop seeds come next: the whole tile-target machinery in
        UnitScheduler is dead weight without seed stock to plant.

        v20: wheat feed top-up moved ahead of land/new-animal purchases
        — a real-replay + local-trace investigation (NOTES.md "v20")
        found the OLD order (land/animals budgeted before wheat top-up)
        left the shed's WHEAT reserve at 0 in 93% of turns where a
        critical-unfed animal existed (204 of 220 sampled turns), because
        buying MORE animals routinely exhausted the budget before
        protecting the ones already owned. Feeding animals we already
        have takes priority over acquiring more; land/new-animal
        purchases can wait a turn without losing anything already paid
        for, an unfed animal cannot.
        """
        orders = []
        budget = state.my_farm.money

        # v25: a small cash floor, untouched by ANY purchase this turn
        # (HIRE, seeds, land, animals, fertilizer alike), during the
        # pre-first-harvest window — see PRE_HARVEST_CASH_RESERVE's
        # config.py comment for the real-match death spiral this guards
        # against (v23 guarded only HIRE's own spend, which v25 real-match
        # data showed still let OTHER orders drain cash to $0 in 28% of
        # games). Subtracting it up front from the working budget makes
        # every affordability check below automatically respect the
        # floor, the same way an already-tight budget does.
        if state.day < PRE_HARVEST_DAY_THRESHOLD:
            budget -= PRE_HARVEST_CASH_RESERVE

        # HIRE, BUY_LAND, and BUY_ANIMAL are day-level decisions (§3.2) whose
        # target counts are cached for the whole day — only submit once, on
        # the first turn of the day, or they'd repeat (and overspend) every
        # turn for the rest of the day.
        if state.hour == 0:
            hires_so_far = state.my_farm.hires_today
            for _ in range(plan.hire_count):
                cost = fib_cost(hires_so_far)
                if cost > budget:
                    break
                orders.append(["HIRE"])
                budget -= cost
                hires_so_far += 1

        for crop, target in plan.crop_targets.items():
            if target <= 0:
                continue
            crop_info = CROP_DATA[crop]
            seeds_held = state.seeds.get(crop, 0)
            target_seed_stock = min(target, 5)
            if seeds_held < target_seed_stock:
                affordable = int(budget // crop_info["seed_cost"])
                to_buy = min(target_seed_stock - seeds_held, affordable)
                if to_buy > 0:
                    orders.append(["BUY_SEED", crop, to_buy])
                    budget -= to_buy * crop_info["seed_cost"]

        # v20: protect animals ALREADY owned (feed top-up) before spending
        # on land or MORE animals — see the priority-order docstring above.
        wheat_orders, budget = self._build_wheat_feed_topup_orders(state, budget)
        orders.extend(wheat_orders)

        if state.hour == 0:
            if plan.buy_land:
                # v16: land_cost (resolved in strategy.py, which already
                # knows which quadrant tier is next) is deducted from the
                # SAME shared budget every other order draws from — found
                # via a real-match replay (NOTES.md "v16") that skipping
                # this let same-turn animal orders get computed against a
                # stale, pre-purchase budget and silently truncated by the
                # game engine once real money ran out mid-order-list
                # (README: "If a player runs out of money mid-order, the
                # order is stopped") — observed as 5 PASTURE structures
                # built but only 2 COW ever bought to fill them.
                orders.append(["BUY_LAND"])
                budget -= plan.land_cost
            animal_orders, budget = self._build_animal_orders(state, plan, budget)
            orders.extend(animal_orders)

        fertilizer_orders, budget = self._build_fertilizer_orders(state, plan, budget)
        orders.extend(fertilizer_orders)
        orders.extend(self._build_sell_orders(state, plan))  # sells earn money, no budget to track

        return orders[:MAX_MARKET_ORDERS_PER_TURN]

    def _build_wheat_feed_topup_orders(self, state: GameState, budget: float) -> tuple:
        """Owned animals need WHEAT every day regardless of how the crop
        portfolio's own WHEAT tile share happens to be doing that day —
        planting/harvest timing (only one crop gets planted per turn per
        the shortfall-based scheduler in UnitScheduler) can leave WHEAT
        production too thin to cover feed demand on top of sales. Top up
        via BUY_PRODUCT (only WHEAT/FERTILIZER can be bought back, README)
        whenever the shed is short of the feed reserve — this closes a real
        gap found via tools/replay_analyze.py's escape-event tracking."""
        animal_count = self._animal_count(state)
        if animal_count <= 0:
            return [], budget
        reserve_target = animal_count * 2
        held = state.shed.get("WHEAT", 0)
        if held >= reserve_target:
            return [], budget
        price = current_price("WHEAT", state)
        if not price:
            return [], budget
        # v20: uses its OWN, more generous ceiling (WHEAT_FEED_BUY_CEILING_MULT)
        # — see its config.py comment. Sharing FERTILIZER_BUY_CEILING_MULT
        # (1.5x) was a real bug: a real-scripted-opponent trace found shed
        # WHEAT stuck at 0 for a full day, healthy cash the whole time,
        # because price had drifted to 1.56x base — just over the old
        # shared ceiling — silently blocking every top-up attempt while
        # animals starved. Missing a wheat top-up risks losing a whole
        # animal ($300-500), a much higher stake than fertilizer's minor
        # forfeited yield bonus, so it's worth paying a steeper premium.
        if price > WHEAT_FEED_BUY_CEILING_MULT * PRODUCT_BASE_PRICE["WHEAT"]:
            return [], budget
        affordable = int(budget // price)
        to_buy = min(reserve_target - held, affordable)
        if to_buy > 0:
            return [["BUY_PRODUCT", "WHEAT", to_buy]], budget - to_buy * price
        return [], budget

    def _build_fertilizer_orders(self, state: GameState, plan: DayPlan, budget: float) -> tuple:
        """Opportunistic top-up via BUY_PRODUCT (only WHEAT/FERTILIZER can be
        bought back, README) whenever there's an active crop portfolio that
        could use the yield boost and the shed is below the small reserve
        target. Collected-from-animals fertilizer counts toward the same
        reserve, so this only fires to fill the gap."""
        if not plan.crop_targets:
            return [], budget
        held = state.shed.get("FERTILIZER", 0)
        if held >= FERTILIZER_RESERVE_TARGET:
            return [], budget
        price = current_price("FERTILIZER", state)
        if not price:
            return [], budget
        # v15: the actual bug found via a "pass"-baseline seed sweep
        # (NOTES.md "v15") — this re-check runs every turn (fertilizer
        # gets consumed mid-day by FERTILIZE), and with no price ceiling
        # it kept re-buying through a self-inflated price spike (FERTILIZER's
        # small T=200 means repeated small buys ratchet price up fast),
        # once observed paying $202 for a single unit of a $100-base item
        # during the exact pre-first-harvest cash-tight window where that
        # money was needed for HIRE instead. A missed fertilize bonus costs
        # far less than chasing an inflated price for one.
        if price > FERTILIZER_BUY_CEILING_MULT * PRODUCT_BASE_PRICE["FERTILIZER"]:
            return [], budget
        affordable = int(budget // price)
        to_buy = min(FERTILIZER_RESERVE_TARGET - held, affordable)
        if to_buy > 0:
            return [["BUY_PRODUCT", "FERTILIZER", to_buy]], budget - to_buy * price
        return [], budget

    def _build_animal_orders(self, state: GameState, plan: DayPlan, budget: float) -> tuple:
        orders = []
        for animal, target in plan.animal_targets.items():
            if target <= 0:
                continue
            info = ANIMAL_DATA[animal]
            owned = state.shed.get(animal, 0)
            for inv in state.inventories:
                owned += inv.get(animal, 0)
            for row in state.my_farm.tiles:
                for cell in row:
                    if isinstance(cell, StructureTile) and cell.animal == animal:
                        owned += 1
            shortfall = target - owned
            if shortfall <= 0:
                continue
            affordable = int(budget // info["cost"])
            to_buy = min(shortfall, affordable)
            if to_buy > 0:
                orders.append(["BUY_ANIMAL", animal, to_buy])
                budget -= to_buy * info["cost"]
        return orders, budget

    def _build_sell_orders(self, state: GameState, plan: DayPlan) -> list:
        """Size each SELL order against MarketModel's hold floor (§5.4)
        instead of dumping the whole shed: hold if the current price is
        already below the floor, otherwise sell only as many units as keep
        the price at or above the floor (spreading large sells across
        turns automatically, since the leftover stays in the shed for the
        next turn's re-evaluation).

        WHEAT is also the only feed source (README: "must be fed wheat
        daily") — reserve one unit per owned animal so a FETCH_WHEAT pickup
        (farm_ops.UnitScheduler) never loses the race against this same-turn
        SELL order and starves an animal into escaping. FERTILIZER has the
        same race against the FERTILIZE mechanic, reserved the same way."""
        orders = []
        # x2 buffer: a unit fetching feed takes at least 2 turns round-trip
        # (pickup, then walk/feed), so a 1-day reserve can still run dry
        # mid-transit on a bad day.
        wheat_reserve = self._animal_count(state) * 2 if plan.sell_thresholds.get("WHEAT") is not None else 0
        fertilizer_reserve = FERTILIZER_RESERVE_TARGET if plan.sell_thresholds.get("FERTILIZER") is not None else 0

        # M6 hardening: shed overflow discards items silently at end-of-day
        # (README, shedCapacity default 100) — once close to full, bypass
        # every hold floor so nothing sitting in the shed gets thrown away
        # for free next end-of-day.
        overflow_risk = sum(state.shed.values()) >= SHED_OVERFLOW_GUARD_THRESHOLD

        for resource, hold_pct in plan.sell_thresholds.items():
            qty = state.shed.get(resource, 0)
            if resource == "WHEAT":
                qty = max(0, qty - wheat_reserve)
            elif resource == "FERTILIZER":
                qty = max(0, qty - fertilizer_reserve)
            if qty <= 0:
                continue
            base_price = PRODUCT_BASE_PRICE.get(resource)
            if base_price is None:
                continue

            # v12: the more of THIS resource already sitting unsold, the
            # less we insist on waiting for a price recovery — see
            # SELL_CAPITULATION_QTY's config comment for why. Reaches full
            # capitulation (floor multiplier 0) at that quantity, well
            # before SHED_OVERFLOW_GUARD_THRESHOLD's total-shed check.
            capitulation = max(0.0, 1 - qty / SELL_CAPITULATION_QTY)
            effective_hold_pct = hold_pct * capitulation

            price_now = current_price(resource, state)
            floor_price = 0.0 if overflow_risk else effective_hold_pct * base_price
            if price_now < floor_price:
                continue  # hold — price already too depressed to sell into
            inventory = state.market_inventory.get(resource, 10000)
            sell_qty = min(qty, max_sell_before_floor(resource, inventory, floor_price))
            if sell_qty > 0:
                orders.append(["SELL", resource, sell_qty])
        return orders

    def _animal_count(self, state: GameState) -> int:
        return sum(
            1 for row in state.my_farm.tiles for cell in row
            if isinstance(cell, StructureTile) and cell.animal is not None
        )


class FarmOpsOrchestrator:
    def __init__(self):
        self.unit_scheduler = UnitScheduler()
        self.market_executor = MarketExecutor()

    def run(self, state: GameState, plan: DayPlan) -> dict:
        unit_actions = self.unit_scheduler.assign(state, plan)
        market_orders = self.market_executor.build_orders(state, plan)
        farmer_action = unit_actions[0] if unit_actions else ["PASS"]
        hand_actions = unit_actions[1:] if len(unit_actions) > 1 else []
        return {
            "farmer": farmer_action,
            "hands": hand_actions,
            "market": market_orders,
        }

# ==== agent.py ====
"""Thin wiring: agent(obs) entrypoint (SDD §3, §7).

Keeps process-local memory (module-level) so StrategyAgent's DayPlan isn't
recomputed every turn — only at the start of each day, per §3.2's
re-evaluation cadence.
"""


_strategy_agent = StrategyAgent()
_farm_ops = FarmOpsOrchestrator()
_memory = {"day_plan": None, "plan_day": None}


def agent(obs):
    state = StateParser.parse(obs)

    if _memory["plan_day"] != state.day:
        _memory["day_plan"] = _strategy_agent.plan(state)
        _memory["plan_day"] = state.day

    return _farm_ops.run(state, _memory["day_plan"])
